// MARK: - Demo Coordinator

class DemoCoordinator: ObservableObject {
    @Published var currentStep: Int = 0
    @Published var hotspotFrames: [String: CGRect] = [:]
    @Published var isCompleted: Bool = false

    let totalSteps = DemoStep.allSteps.count

    var currentDemoStep: DemoStep {
        guard !DemoStep.allSteps.isEmpty else {
            fatalError("DemoStep.allSteps must not be empty")
        }
        return DemoStep.allSteps[min(currentStep, DemoStep.allSteps.count - 1)]
    }

    var currentHotspotFrame: CGRect {
        if currentStep >= DemoStep.allSteps.count - 1 {
            // Last step = full screen
            return .zero
        }
        return hotspotFrames[currentDemoStep.hotspotId] ?? estimatedFrame(for: currentDemoStep.hotspotId)
    }

    func advanceStep() {
        if currentStep < totalSteps - 1 {
            let nextStep = DemoStep.allSteps[currentStep + 1]
            // Collapse panel if next step requires it
            if nextStep.collapsePanel {
                NotificationCenter.default.post(name: .collapseSoundPanel, object: nil)
            }
            withAnimation(.spring(response: 0.4, dampingFraction: 0.8)) {
                currentStep += 1
            }
        } else {
            withAnimation {
                isCompleted = true
            }
        }
    }

    func skip() {
        withAnimation {
            isCompleted = true
        }
